def _gitlab_instance_from_payload(payload: dict) -> str:
    """Attributes a (already authenticated) webhook payload to one configured GitLab instance by the
    HOST of its project URL. Project ids are only unique per instance, so scanning "project 42" against
    the wrong instance would audit and attribute a different repo. Unknown host -> 403 (fail-closed,
    project rule #7): never fall back to the primary instance's credentials."""
    from core import gitlab_instances
    project = payload.get("project") or {}
    repository = payload.get("repository") or {}
    for candidate in (project.get("web_url"), project.get("git_http_url"), project.get("http_url"),
                      repository.get("homepage"), repository.get("git_http_url")):
        inst = gitlab_instances.instance_for_host(candidate) if candidate else None
        if inst:
            return inst.key
    raise HTTPException(status_code=403, detail="webhook origin host is not a configured GitLab instance")



