@router.post("/api/gitlab/push-webhook")
async def gitlab_push_webhook(request: Request, background_tasks: BackgroundTasks):
    """
    GitLab Push Webhook listener.
    Automatically detects commits pushed by developers, filters for monitored baseline branches
    (develop, desarrollo, main, master), and triggers an on-demand background Omni-Audit on the affected project.
    """
    _require_gitlab_webhook_token(request)
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="body is not JSON")

    if payload.get("object_kind") != "push":
        return {"status": "ignored", "reason": f"object_kind={payload.get('object_kind')}"}

    # Ignore branch deletion events (after SHA is all zeros)
    after_sha = payload.get("after") or ""
    if after_sha == "0000000000000000000000000000000000000000":
        return {"status": "ignored", "reason": "branch deletion event"}

    ref = payload.get("ref") or ""
    if not ref.startswith("refs/heads/"):
        return {"status": "ignored", "reason": f"not a branch push (ref={ref})"}

    branch = ref.replace("refs/heads/", "")
    from auditors.gitlab_integration import is_monitored_branch
    if not is_monitored_branch(branch):
        return {
            "status": "ignored",
            "reason": f"branch '{branch}' is not in monitored baseline list (develop, desarrollo, main, master)",
            "branch": branch
        }

    project = payload.get("project") or {}
    project_id = project.get("id") or payload.get("project_id")
    if not project_id:
        raise HTTPException(status_code=400, detail="missing project id in push payload")

    # Never trust repo URLs carried in the payload (they would be cloned with the GitLab token
    # embedded): pass only the project id and let GitLabIntegrator resolve it via the GitLab API.
    background_tasks.add_task(_run_push_scan_bg, project_id, branch, _gitlab_instance_from_payload(payload))
    commits_count = payload.get("total_commits_count", len(payload.get("commits", [])))
    return {
        "status": "accepted",
        "project_id": project_id,
        "branch": branch,
        "commits_count": commits_count,
        "after_sha": after_sha
    }



@router.get("/api/gitlab/projects/{project_id:path}/branches")
def list_project_branches(project_id: str, instance: Optional[str] = None):
    """Branches of a GitLab project, each with whether it has its own audited asset and whether it changed since its last analysis
    (`change_state`, `rescan_allowed`; see core/change_detection.py). Asks GitLab live, so the answer reflects the current heads."""
    try:
        from auditors.gitlab_integration import GitLabIntegrator
        from core import change_detection
        integ = GitLabIntegrator(instance=instance)
        proj = integ.get_project_details(project_id)
        if not proj:
            raise HTTPException(status_code=404, detail="Proyecto no encontrado")
        branches = integ.list_branches(proj["id"])
        path_ns = proj["path_with_namespace"]
        change_detection.refresh_project(integ.instance, path_ns)
        names = [integ.instance.asset_name(path_ns, b["name"]) for b in branches]
        states = {x["asset_name"]: x for x in change_detection.asset_states(assets=names)}
        with db_manager.get_db_cursor() as cur:
            cur.execute("SELECT asset_name, last_audit FROM public.infra_inventory WHERE asset_name = ANY(%s)", (names,))
            audited = {r[0]: r[1] for r in cur.fetchall()}
        for b in branches:
            name = integ.instance.asset_name(path_ns, b["name"])
            st = states.get(name)
            b["asset_name"] = name
            b["last_audit"] = audited.get(name)
            b["analyzed_commit"] = st["analyzed_commit"] if st else None
            b["change_state"] = st["state"] if st else change_detection.SIN_ANALISIS
            b["rescan_allowed"] = st["rescan_allowed"] if st else True
            b["is_fleet_branch"] = st["is_fleet_branch"] if st else False
        return {"project": path_ns, "project_id": proj["id"], "instance": integ.instance.key, "branches": branches}
    except HTTPException:
        raise
    except KeyError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=502, detail=str(e))


@router.post("/api/gitlab/projects/{project_id:path}/scan-branch")
def scan_project_branch(project_id: str, branch: str, instance: Optional[str] = None):
    """Queue an audit of one branch as its own asset (GitLab/<path>@<branch>). Runs in the scan worker; poll the asset for results."""
    try:
        from auditors.gitlab_integration import enqueue_branch_scan, UnchangedSinceLastAnalysis
        try:
            return {"status": "queued", **enqueue_branch_scan(project_id, branch, instance)}
        except UnchangedSinceLastAnalysis as e:
            raise HTTPException(status_code=409, detail=str(e))
    except HTTPException:
        raise
    except (ValueError, LookupError, KeyError) as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


