# --- change detection: re-analyze only what changed (core/change_detection.py) ---------------------------------------------------

class ChangeSelectionModel(BaseModel):
    prefix: Optional[str] = None          # "GitLab/grupo/" selects every GitLab asset under that group
    asset: Optional[List[str]] = None     # or an explicit list of asset names


def _selection(body: ChangeSelectionModel):
    if not body.prefix and not body.asset:
        raise HTTPException(status_code=400, detail="Indique un grupo (prefix) o una lista de activos (asset)")
    if body.prefix and not re.match(r"^GitLab\d*/", body.prefix):
        raise HTTPException(status_code=400, detail="El prefijo debe ser de un grupo de GitLab (GitLab/... o GitLabN/...)")
    return body.prefix, body.asset


@router.get("/api/gitlab/changes")
def gitlab_changes(prefix: Optional[str] = None):
    """Change state of every GitLab asset (optionally under a group prefix) from the stored heads; no GitLab call. States: CAMBIOS,
    SIN_ANALISIS, REGLAS_NUEVAS, AL_DIA, RAMA_ELIMINADA, SIN_VERIFICAR, EN_COLA. `rescan_allowed` is true only for CAMBIOS/SIN_ANALISIS."""
    from core import change_detection
    states = [s for s in change_detection.asset_states(prefix=prefix) if access_scope.allows(s["asset_name"])]   # ADR-0019
    return {"engine_version": change_detection.engine_version(), "summary": change_detection.summarize(states), "assets": states}


@router.post("/api/gitlab/changes/refresh")
def gitlab_changes_refresh(body: ChangeSelectionModel):
    """Ask GitLab now for the latest commit of every branch in the selection (one call per project), then return the states."""
    from core import change_detection
    prefix, assets = _selection(body)
    names = [n for n in change_detection.select_asset_names(prefix, assets) if access_scope.allows(n)]   # ADR-0019
    if len(names) > change_detection.MAX_ASSETS_PER_REQUEST:
        raise HTTPException(status_code=400, detail=f"La selección tiene {len(names)} activos; elija un subgrupo")
    r = change_detection.refresh_assets(names)
    states = change_detection.asset_states(assets=names)
    return {"refresh_failed": r["failed"], "summary": change_detection.summarize(states), "assets": states}


@router.post("/api/gitlab/rescan-changed")
def gitlab_rescan_changed(body: ChangeSelectionModel):
    """Re-analyze, as one batch, only the selected assets whose code changed since their last analysis (or that were never analyzed).
    Assets without changes are skipped and reported. Follow the batch with GET /api/gitlab/rescan-batch/{batch_id}."""
    from core import change_detection
    prefix, assets = _selection(body)
    try:
        r = change_detection.enqueue_changed(prefix, assets)
    except LookupError as e:
        raise HTTPException(status_code=404, detail=str(e))
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    if not r["batch_id"]:
        raise HTTPException(status_code=409, detail="Ningún activo de la selección tiene cambios desde su último análisis")
    agent_ledger.record_action("gitlab_rescan_changed",
                               f"Re-análisis de lo que cambió: {len(r['queued'])} en cola, {len(r['already_queued'])} ya en curso, "
                               f"{len(r['skipped'])} sin cambios", outcome="queued", actor="analyst", entity_type="scan_batch",
                               entity_id=r["batch_id"], detail={"prefix": prefix, "assets": assets, "queued": r["queued"],
                                                                "already_queued": r["already_queued"], "skipped": r["skipped"]})
    return r


@router.get("/api/gitlab/rescan-batch/{batch_id}")
def gitlab_rescan_batch(batch_id: str):
    """Progress of a re-analysis batch: total, done, failed, running, queued, percent and the asset running now."""
    from core import change_detection
    p = change_detection.batch_progress(batch_id)
    if not p["total"]:
        raise HTTPException(status_code=404, detail="Lote no encontrado")
    return p


@router.get("/api/gitlab/branch-diff", summary="Diferencias de hallazgos de una rama contra la rama principal")
def gitlab_branch_diff(asset: str, base: Optional[str] = None):
    """Open findings (vulnerabilities and compliance) of a branch asset compared with the project's main branch (the fleet branch in
    gitlab_branch_heads, or `base`). Compared by (rule, file) with counts, so a line that only moved is not reported as new.
    Returns what the branch adds (`only_in_branch`) and what it no longer has (`only_in_base`)."""
    from core import gitlab_instances
    inst, path, branch = gitlab_instances.parse_asset_name(asset)
    if inst is None or not path:
        raise HTTPException(status_code=400, detail="El activo no es una rama de un proyecto GitLab")
    with db_manager.get_db_cursor() as cur:
        if not base:
            cur.execute("""SELECT asset_name FROM public.gitlab_branch_heads
                            WHERE instance = %s AND project_path = %s AND is_fleet_branch ORDER BY checked_at DESC NULLS LAST LIMIT 1""",
                        (inst.key, path))
            row = cur.fetchone()
            base = row[0] if row else None
        if not base:
            raise HTTPException(status_code=404, detail="No se conoce la rama principal de este proyecto (aún no se ha consultado GitLab)")
        if base == asset:
            return {"asset": asset, "base": base, "is_base": True, "only_in_branch": [], "only_in_base": [], "common": None}
        if not access_scope.allows(base):
            raise HTTPException(status_code=403, detail="Acceso denegado: la rama principal está fuera de su alcance.")
        cur.execute("""SELECT i.asset_name, v.cve_id, v.url_path, COALESCE(v.real_severity, v.severity), v.finding_category
                         FROM public.vulnerability_log v JOIN public.infra_inventory i ON i.id = v.asset_id
                        WHERE i.asset_name = ANY(%s) AND v.status NOT IN ('RESOLVED', 'SUPPRESSED')
                          AND v.finding_category IN ('VULNERABILITY', 'COMPLIANCE')""", ([asset, base],))
        rows = cur.fetchall()
    from auditors.auditor_sonarqube import file_of
    counts = {asset: {}, base: {}}
    sample = {}
    for name, cve, up, sev, cat in rows:
        key = (cve, file_of(up))
        counts[name][key] = counts[name].get(key, 0) + 1
        sample.setdefault(key, {"cve_id": cve, "file": key[1], "severity": sev, "category": cat})
    def diff(a, b):
        return sorted(({**sample[k], "count": counts[a][k] - counts[b].get(k, 0)} for k in counts[a] if counts[a][k] > counts[b].get(k, 0)),
                      key=lambda x: (-x["count"], x["cve_id"]))
    common = sum(min(n, counts[base].get(k, 0)) for k, n in counts[asset].items())
    return {"asset": asset, "base": base, "is_base": False, "only_in_branch": diff(asset, base), "only_in_base": diff(base, asset),
            "common": common}
